export const workerAlchemyRun = (context: TemplateContext): string =>
  `import * as Alchemy from "alchemy";
import * as Cloudflare from "alchemy/Cloudflare";
import * as Effect from "effect/Effect";

import AppWorkerLive, { AppWorker } from "./src/app.worker.ts";

export default Alchemy.Stack(
  "${context.slug}",
  {
    providers: Cloudflare.providers(),
    state: Cloudflare.state(),
  },
  Effect.gen(function* () {
    const db = yield* Cloudflare.D1.Database("AppData", {
      migrationsDir: "./migrations",
    });

    const worker = yield* AppWorker;

    return {
      url: worker.url.as<string>(),
      databaseId: db.databaseId,
    };
  }).pipe(Effect.provide(AppWorkerLive)),
);
`;

